-- FFH-P08 account settings and security (design: docs/FFH-P08_PROPOSAL.md §11, binding; R1–R11 approved).
-- Generated by scripts/p08/build-migration.py from scripts/p08/migration-head.sql + migration-tail.sql plus three
-- RPC bodies copied verbatim from earlier migrations (only their sign-in guard changes). Do not edit by hand.
--
-- What it adds:
--   * private.session_ok(): the one assurance predicate. The JWT's session_id must name a LIVE auth.sessions row
--     of auth.uid(); for a person with an FFH-approved authenticator, the JWT and that row must both be aal2 and
--     the row's factor_id must be an approved factor. No security decision compares JWT and database clocks.
--   * Every authorization path requires it: the four household helpers (so every financial/household policy),
--     the profiles and households-insert policies, and every RPC executable by authenticated.
--   * One lock order for membership changes: household row, then invitation rows, then membership rows.
--   * FFH factor registry, single-use recent re-authentication proofs and a security event log (private schema,
--     no grants to anon/authenticated).

begin;

-- ---------------------------------------------------------------------------------------------------------------
-- Private state
-- ---------------------------------------------------------------------------------------------------------------
create table private.mfa_approved_factors (
  factor_id uuid primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  approved_at timestamptz not null default now()
);
create index mfa_approved_factors_user_idx on private.mfa_approved_factors (user_id);

create table private.reauth_uses (
  session_id uuid not null,
  purpose text not null check (purpose in ('password_change', 'mfa_approve', 'mfa_revoke', 'delete_account')),
  user_id uuid not null references auth.users(id) on delete cascade,
  used_at timestamptz not null default now(),
  primary key (session_id, purpose)
);

-- No foreign key: an account-deletion or Owner-reset row must outlive the account it describes. No secrets, no email.
create table private.security_events (
  id bigint generated always as identity primary key,
  user_id uuid not null,
  event text not null check (event in ('password_changed', 'mfa_approved', 'mfa_revoked', 'account_deleted', 'owner_mfa_reset')),
  detail text,
  created_at timestamptz not null default now()
);

revoke all on private.mfa_approved_factors, private.reauth_uses, private.security_events from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- The assurance predicate
-- ---------------------------------------------------------------------------------------------------------------
create or replace function private.has_approved_factor(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from private.mfa_approved_factors f where f.user_id = p_user);
$$;

create or replace function private.session_ok()
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_claims jsonb;
  v_session uuid;
  v_aal text;
  v_factor uuid;
  v_not_after timestamptz;
begin
  if v_user is null then
    return false;
  end if;
  begin
    v_claims := auth.jwt();
    v_session := (v_claims ->> 'session_id')::uuid;
  exception when others then
    return false;
  end;
  if v_session is null or jsonb_typeof(v_claims) <> 'object' then
    return false;
  end if;
  select s.aal::text, s.factor_id, s.not_after into v_aal, v_factor, v_not_after
  from auth.sessions s
  where s.id = v_session and s.user_id = v_user;
  if not found or (v_not_after is not null and v_not_after <= now()) then
    return false;
  end if;
  if not private.has_approved_factor(v_user) then
    return true;
  end if;
  return coalesce(v_claims ->> 'aal', '') = 'aal2'
    and v_aal = 'aal2'
    and v_factor is not null
    and exists (select 1 from private.mfa_approved_factors f where f.user_id = v_user and f.factor_id = v_factor);
end;
$$;

revoke all on function private.has_approved_factor(uuid), private.session_ok() from public, anon, authenticated;
-- RLS policies evaluate as the caller, so the predicate itself must be executable by authenticated.
grant execute on function private.session_ok() to authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- Household helpers: every household and financial policy goes through one of these four.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function private.is_household_member(target_household_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.session_ok() and exists (
    select 1
    from public.household_members hm
    where hm.household_id = target_household_id
      and hm.user_id = (select auth.uid())
  );
$$;

create or replace function private.can_read_household(target_household_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.session_ok() and exists (
    select 1
    from public.household_members hm
    where hm.household_id = target_household_id
      and hm.user_id = (select auth.uid())
  );
$$;

create or replace function private.can_write_household_financials(target_household_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.session_ok() and exists (
    select 1
    from public.household_members hm
    where hm.household_id = target_household_id
      and hm.user_id = (select auth.uid())
      and hm.role in ('owner', 'member')
  );
$$;

create or replace function private.is_household_owner(target_household_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.session_ok() and exists (
    select 1
    from public.household_members hm
    where hm.household_id = target_household_id
      and hm.user_id = (select auth.uid())
      and hm.role = 'owner'
  );
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- The four policies that did not go through a helper.
-- ---------------------------------------------------------------------------------------------------------------
drop policy "profiles_select_self" on public.profiles;
drop policy "profiles_insert_self" on public.profiles;
drop policy "profiles_update_self" on public.profiles;
drop policy "households_insert_creator" on public.households;

create policy "profiles_select_self" on public.profiles for select to authenticated
  using (id = (select auth.uid()) and (select private.session_ok()));
create policy "profiles_insert_self" on public.profiles for insert to authenticated
  with check (id = (select auth.uid()) and (select private.session_ok()));
create policy "profiles_update_self" on public.profiles for update to authenticated
  using (id = (select auth.uid()) and (select private.session_ok()))
  with check (id = (select auth.uid()) and (select private.session_ok()));
create policy "households_insert_creator" on public.households for insert to authenticated
  with check (created_by = (select auth.uid()) and (select private.session_ok()));

-- ---------------------------------------------------------------------------------------------------------------
-- Membership RPCs: household row first, then invitation, then membership (proposal §11.4).
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.accept_household_invitation(p_token text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_hash text;
  v_household uuid;
  v_invite public.household_invitations%rowtype;
begin
  if v_user is null or not private.session_ok() then
    raise exception 'permission denied: not signed in' using errcode = '42501';
  end if;
  if p_token is null or p_token !~ '^[A-Za-z0-9_-]{43}$' then
    raise exception 'permission denied: this invitation is not valid' using errcode = '42501';
  end if;
  v_hash := encode(sha256(convert_to(p_token, 'UTF8')), 'hex');

  -- 1. Non-locking lookup, only to learn which household to lock.
  select i.household_id into v_household from public.household_invitations i where i.token_hash = v_hash;
  if not found then
    raise exception 'permission denied: this invitation is not valid' using errcode = '42501';
  end if;
  -- 2. Household row first (account deletion takes the same lock first).
  perform 1 from public.households h where h.id = v_household for update;
  if not found then
    raise exception 'permission denied: this invitation is not valid' using errcode = '42501';
  end if;
  -- 3. Then the invitation, re-validated under the household lock.
  select * into v_invite from public.household_invitations
  where token_hash = v_hash
  for update;
  if not found or v_invite.household_id <> v_household
     or v_invite.accepted_at is not null or v_invite.expires_at <= now() then
    raise exception 'permission denied: this invitation is not valid' using errcode = '42501';
  end if;
  if exists (select 1 from public.household_members where user_id = v_user) then
    raise exception 'permission denied: you already belong to a household' using errcode = '42501';
  end if;

  -- The UNIQUE(user_id) constraint, not this prior SELECT, is the final
  -- concurrency and household-creation invariant.
  begin
    insert into public.household_members (household_id, user_id, role)
    values (v_invite.household_id, v_user, v_invite.role);
  exception when unique_violation then
    raise exception 'permission denied: you already belong to a household' using errcode = '42501';
  end;
  update public.household_invitations
  set accepted_at = now(), accepted_by = v_user
  where id = v_invite.id;

  return v_invite.household_id;
end;
$$;

-- Owner only: change another person's role between member and viewer.
create or replace function public.set_household_member_role(p_household_id uuid, p_user_id uuid, p_role public.household_role)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null or not private.session_ok() or not private.is_household_owner(p_household_id) then
    raise exception 'permission denied: only the household owner can change roles' using errcode = '42501';
  end if;
  if p_role is null or p_role not in ('member', 'viewer') then
    raise exception 'setup: role must be member or viewer' using errcode = '22023';
  end if;
  perform 1 from public.households h where h.id = p_household_id for update;
  update public.household_members
  set role = p_role
  where household_id = p_household_id and user_id = p_user_id and role <> 'owner';
  if not found then
    raise exception 'permission denied: that person cannot be changed' using errcode = '42501';
  end if;
end;
$$;

-- Owner only: remove another person from the household. The owner is never removed.
create or replace function public.remove_household_member(p_household_id uuid, p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null or not private.session_ok() or not private.is_household_owner(p_household_id) then
    raise exception 'permission denied: only the household owner can remove people' using errcode = '42501';
  end if;
  perform 1 from public.households h where h.id = p_household_id for update;
  delete from public.household_members
  where household_id = p_household_id and user_id = p_user_id and role <> 'owner';
  if not found then
    raise exception 'permission denied: that person cannot be removed' using errcode = '42501';
  end if;
end;
$$;
